// Some portions generated by Claude Code
package org.eclipse.rdf4j.common.iteration;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.HashSet;
import java.util.List;
import java.util.NoSuchElementException;

import org.junit.jupiter.api.Test;

/**
 * Every pass-through iteration forwards a cooperative cancellation request to the iterations it reads from.
 */
class CooperativeCancellationForwardingTest {

	@Test
	void singleSourceWrappersForwardToTheirSource() {
		List<Wrapping> wrappers = List.of(
				source -> new FilterIteration<>(source) {
					@Override
					protected boolean accept(Integer value) {
						return true;
					}

					@Override
					protected void handleClose() {
					}
				},
				source -> new ConvertingIteration<Integer, Integer>(source) {
					@Override
					protected Integer convert(Integer value) {
						return value;
					}
				},
				source -> new ExceptionConvertingIteration<Integer, RuntimeException>(source) {
					@Override
					protected RuntimeException convert(RuntimeException exception) {
						return exception;
					}
				},
				source -> new DistinctIteration<>(source, new HashSet<>()),
				source -> new OffsetIteration<>(source, 1),
				source -> new ReducedIteration<>(source),
				source -> new LimitIteration<>(source, 1),
				source -> new UnionIteration<>(source),
				source -> new DualUnionIteration<>(null, source, new EmptyIteration<>()));
		for (Wrapping wrapping : wrappers) {
			Source source = new Source();
			CloseableIteration<Integer> wrapper = wrapping.wrap(source);
			try {
				assertTrue(wrapper.hasNext(), "lazily opened wrappers open their source on first use");
				assertTrue(CooperativeCancellation.forward(wrapper), wrapper.getClass().getName());
				assertEquals(1, source.cancellationRequests, wrapper.getClass().getName());
			} finally {
				wrapper.close();
			}
			assertFalse(CooperativeCancellation.forward(wrapper), "a closed wrapper must decline");
		}
	}

	@Test
	void setOperationsForwardToBothArguments() {
		Source left = new Source();
		Source right = new Source();
		try (IntersectIteration<Integer> intersect = new IntersectIteration<>(left, right)) {
			assertTrue(intersect.requestCancellation());
			assertEquals(1, left.cancellationRequests);
			assertEquals(1, right.cancellationRequests);
		}
		left = new Source();
		right = new Source();
		try (MinusIteration<Integer> minus = new MinusIteration<>(left, right)) {
			assertTrue(minus.requestCancellation());
			assertEquals(1, left.cancellationRequests);
			assertEquals(1, right.cancellationRequests);
		}
	}

	@Test
	void delayedIterationForwardsOnceItsIterationExists() {
		Source source = new Source();
		DelayedIteration<Integer> delayed = new DelayedIteration<>() {
			@Override
			protected CloseableIteration<? extends Integer> createIteration() {
				return source;
			}
		};
		try {
			assertFalse(delayed.requestCancellation(), "nothing to forward before the iteration is created");
			delayed.hasNext();
			assertTrue(delayed.requestCancellation());
			assertEquals(1, source.cancellationRequests);
		} finally {
			delayed.close();
		}
	}

	@Test
	void lookAheadIterationRecordsTheRequestForPolling() {
		LookAheadIteration<Integer> lookAhead = new LookAheadIteration<>() {
			@Override
			protected Integer getNextElement() {
				return isCancellationRequested() ? null : 1;
			}

			@Override
			protected void handleClose() {
			}
		};
		try {
			assertFalse(lookAhead.isCancellationRequested());
			assertFalse(lookAhead.requestCancellation(), "the default has no source to forward to");
			assertTrue(lookAhead.isCancellationRequested());
		} finally {
			lookAhead.close();
		}
	}

	@FunctionalInterface
	private interface Wrapping {
		CloseableIteration<Integer> wrap(CloseableIteration<Integer> source);
	}

	private static final class Source implements CloseableIteration<Integer>, CooperativeCancellation {
		private int remaining = 3;
		private int cancellationRequests;

		@Override
		public boolean hasNext() {
			return remaining > 0;
		}

		@Override
		public Integer next() {
			if (remaining <= 0) {
				throw new NoSuchElementException();
			}
			return remaining--;
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
		}

		@Override
		public boolean requestCancellation() {
			cancellationRequests++;
			return true;
		}
	}
}
